import{_ as t,o as a,c as h,a3 as i}from"./chunks/framework.DX_KL3e0.js";const c="/help/screenshots/tai-san/tong-quan.png",o="/help/screenshots/tai-san/them-phan-cung.png",p=JSON.parse('{"title":"Quản lý Tài sản","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/tai-san.md","filePath":"chuc-nang/tai-san.md","lastUpdated":1782639524000}'),s={name:"chuc-nang/tai-san.md"};function e(r,n,l,g,u,d){return a(),h("div",null,[...n[0]||(n[0]=[i('<h1 id="quan-ly-tai-san" tabindex="-1">Quản lý Tài sản <a class="header-anchor" href="#quan-ly-tai-san" aria-label="Permalink to &quot;Quản lý Tài sản&quot;">​</a></h1><p>Module <strong>Quản lý Tài sản</strong> giúp doanh nghiệp theo dõi toàn bộ tài sản: phần cứng, phần mềm, tên miền và tài khoản email — kèm thông tin cấp phát và lịch sử thay đổi.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/asset-management</code> (menu <strong>Quản lý Tài sản</strong> ở nhóm <em>Điều Hướng</em>).</li><li><strong>Ai dùng được:</strong> Super Admin, Admin (mặc định không có quyền Xóa), Quản lý (chỉ xem theo cấu hình).</li><li><strong>Phân hệ:</strong> Phần cứng · Phần mềm · Tên miền · Email.</li></ul></div><h2 id="giao-dien-chinh" tabindex="-1">Giao diện chính <a class="header-anchor" href="#giao-dien-chinh" aria-label="Permalink to &quot;Giao diện chính&quot;">​</a></h2><p><img src="'+c+'" alt="Trang Quản lý Tài sản"></p><p>Trang gồm: thẻ <strong>thống kê</strong> (tổng số tài sản theo loại) → <strong>bộ lọc &amp; tìm kiếm</strong> → <strong>danh sách tài sản</strong>.</p><h2 id="cac-phan-he" tabindex="-1">Các phân hệ <a class="header-anchor" href="#cac-phan-he" aria-label="Permalink to &quot;Các phân hệ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phân hệ</th><th>Đường dẫn</th><th>Dùng để</th></tr></thead><tbody><tr><td><strong>Phần cứng</strong></td><td><code>/asset-management/hardware</code></td><td>Máy tính, thiết bị, đồ dùng có quản lý serial/cấp phát.</td></tr><tr><td><strong>Phần mềm</strong></td><td><code>/asset-management/software</code></td><td>Bản quyền, license, gói phần mềm.</td></tr><tr><td><strong>Tên miền</strong></td><td><code>/asset-management/domains</code></td><td>Domain công ty và thông tin liên quan.</td></tr><tr><td><strong>Email</strong></td><td><code>/asset-management/email-accounts</code></td><td>Tài khoản email cấp cho nhân sự.</td></tr></tbody></table><h2 id="thao-tac-chinh" tabindex="-1">Thao tác chính <a class="header-anchor" href="#thao-tac-chinh" aria-label="Permalink to &quot;Thao tác chính&quot;">​</a></h2><h3 id="them-tai-san-moi" tabindex="-1">Thêm tài sản mới <a class="header-anchor" href="#them-tai-san-moi" aria-label="Permalink to &quot;Thêm tài sản mới&quot;">​</a></h3><ol><li>Mở phân hệ tương ứng (ví dụ <strong>Phần cứng</strong>).</li><li>Nhấn nút <strong>Thêm mới</strong> ở góc phải header.</li><li>Điền thông tin trong cửa sổ hiện ra: tên, loại, ngày cấp…</li><li>Gán <strong>Người phụ trách</strong> theo cơ cấu tổ chức (xem mục dưới).</li><li>Nhấn <strong>Lưu</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Chọn người phụ trách theo cơ cấu tổ chức</p><p>Với <strong>Tên miền</strong>, <strong>Email</strong> và <strong>Phần mềm</strong>, ô chọn người phụ trách đi theo cây cơ cấu: chọn <strong>Công ty → Phòng ban → Bộ phận</strong>, dừng ở cấp nào thì danh sách nhân sự lọc đúng nhánh đó (mỗi ô đều có tìm kiếm). Người được gán phụ trách sẽ thấy tài sản này trong <a href="/help/chuc-nang/tra-cuu.html">Tra cứu Tài sản</a>.</p></div><p><img src="'+o+'" alt="Modal thêm tài sản mới — nhập thông tin cơ bản"></p><div class="tip custom-block"><p class="custom-block-title">Cần quyền <code>Thêm</code></p><p>Nút <strong>Thêm mới</strong> chỉ hiện nếu tài khoản của bạn có quyền <code>Thêm</code> trên module này. Nếu không thấy nút, liên hệ Admin. Xem <a href="/help/bat-dau/phan-quyen.html">Phân quyền</a>.</p></div><h3 id="chinh-sua-cap-phat" tabindex="-1">Chỉnh sửa / Cấp phát <a class="header-anchor" href="#chinh-sua-cap-phat" aria-label="Permalink to &quot;Chỉnh sửa / Cấp phát&quot;">​</a></h3><ol><li>Nhấn vào tài sản trong danh sách để mở chi tiết.</li><li>Cập nhật thông tin hoặc đổi người sử dụng.</li><li>Nhấn <strong>Lưu</strong> — thay đổi được ghi vào <a href="/help/chuc-nang/lich-su.html">Lịch sử</a>.</li></ol><h3 id="xoa-tai-san" tabindex="-1">Xóa tài sản <a class="header-anchor" href="#xoa-tai-san" aria-label="Permalink to &quot;Xóa tài sản&quot;">​</a></h3><p>Việc xóa tài sản thường đi qua <strong>luồng duyệt</strong> thay vì xóa trực tiếp:</p><ol><li>Gửi <strong>yêu cầu xóa</strong> từ chi tiết tài sản.</li><li>Người có quyền duyệt xử lý tại <a href="/help/chuc-nang/duyet-yeu-cau.html">Duyệt yêu cầu → Xóa tài sản</a>.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Mặc định <strong>Admin không có quyền Xóa</strong> tài sản — chỉ Super Admin. Quy trình duyệt giúp tránh xóa nhầm và lưu vết.</p></div><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><h2 id="cau-hinh-lien-quan" tabindex="-1">Cấu hình liên quan <a class="header-anchor" href="#cau-hinh-lien-quan" aria-label="Permalink to &quot;Cấu hình liên quan&quot;">​</a></h2><p>Admin có thể quản lý danh mục loại tài sản và người nhận nhắc bảo trì tại <a href="/help/quan-tri/cau-hinh-tai-san.html">Cấu Hình Tài Sản</a>.</p><p><strong>Không thấy menu Quản lý Tài sản?</strong> Module này mặc định dành cho Super Admin/Admin. Nếu bạn là Quản lý/Người dùng, cần được Admin cấp quyền.</p><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/tra-cuu.html">Tra cứu tài sản</a> · <a href="/help/chuc-nang/lich-su.html">Lịch sử</a> · <a href="/help/chuc-nang/duyet-yeu-cau.html">Duyệt yêu cầu</a></p>',26)])])}const b=t(s,[["render",e]]);export{p as __pageData,b as default};
